<script>document.addEventListener('DOMContentLoaded',function(){const q=document.getElementById('service-search'),s=document.getElementById('service-status');function filter(){document.querySelectorAll('#services-table tbody tr,.service-mobile-card').forEach(function(row){const okName=!q.value||row.dataset.name.includes(q.value.toLowerCase());const okStatus=!s.value||row.dataset.status===s.value;row.dataset.hidden=!(okName&&okStatus);row.style.display=okName&&okStatus?'':'none';});}q.addEventListener('input',filter);s.addEventListener('change',filter);document.addEventListener('click',function(event){const link=event.target.closest('a[href*="/admin/portal/servicios/"]');if(!link||/\/canchas\//.test(link.getAttribute('href')||''))return;event.preventDefault();fetch(link.href,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo cargar la configuración');return response.text();}).then(function(html){const doc=new DOMParser().parseFromString(html,'text/html'),panel=doc.querySelector('.service-modal-panel');if(!panel)throw new Error('No se encontró el panel');const backdrop=document.createElement('div');backdrop.className='service-open-backdrop';backdrop.appendChild(panel);document.body.appendChild(backdrop);const close=backdrop.querySelector('.service-modal-close');if(close)close.addEventListener('click',function(){event.preventDefault();backdrop.remove();});}).catch(function(){window.location.href=link.href;});});});</script>
