<script>document.addEventListener('click',function(event){const link=event.target.closest('a[href*="/admin/portal/servicios/"]');if(!link||link.getAttribute('href').includes('/canchas/'))return;event.preventDefault();event.stopImmediatePropagation();fetch(link.href,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo cargar la configuración');return response.text();}).then(function(html){const doc=new DOMParser().parseFromString(html,'text/html'),panel=doc.querySelector('.service-modal-panel');if(!panel)throw new Error('No se encontró el panel');doc.querySelectorAll('style').forEach(function(style,index){const marker='service-modal-style-'+index;if(document.head.querySelector('[data-service-modal-style="'+marker+'"]'))return;const clone=document.createElement('style');clone.dataset.serviceModalStyle=marker;clone.setAttribute('data-service-modal-style',marker);clone.textContent=style.textContent;document.head.appendChild(clone);});panel.classList.add('service-editor');const backdrop=document.createElement('div');backdrop.className='service-open-backdrop';backdrop.appendChild(panel);document.body.appendChild(backdrop);const close=backdrop.querySelector('.service-modal-close');if(close)close.addEventListener('click',function(closeEvent){closeEvent.preventDefault();backdrop.remove();});}).catch(function(){window.location.href=link.href;});},true);</script>
