<script>function portalDuracionHsMinutos(root){(root||document).querySelectorAll('input[name="duration_minutes"]:not([data-hs-minutos])').forEach(function(input){const total=Math.max(0,parseInt(input.value||'0',10)||0),wrap=document.createElement('div');wrap.className='duration-hm';wrap.innerHTML='<input class="form-control" type="number" name="duration_hours" min="0" max="23" value="'+Math.floor(total/60)+'" aria-label="Horas"><span>h</span><input class="form-control" type="number" name="duration_minutes_part" min="0" max="59" step="15" value="'+(total%60)+'" aria-label="Minutos"><span>min</span>';input.parentElement.firstChild.nodeValue='Duración del turno';input.dataset.hsMinutos='1';input.replaceWith(wrap);});}new MutationObserver(function(){document.querySelectorAll('.service-open-backdrop').forEach(portalDuracionHsMinutos);}).observe(document.body,{childList:true,subtree:true});</script>
