<script>(function(){function refreshServices(){var url=new URL(window.location.href);url.searchParams.set('section','servicios');fetch(url.toString(),{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo actualizar la lista');return response.text();}).then(function(html){var doc=new DOMParser().parseFromString(html,'text/html'),currentTable=document.querySelector('.portal-services .service-table-wrap'),currentMobile=document.querySelector('.portal-services .service-mobile'),newTable=doc.querySelector('.portal-services .service-table-wrap'),newMobile=doc.querySelector('.portal-services .service-mobile');if(currentTable&&newTable)currentTable.replaceWith(newTable);if(currentMobile&&newMobile)currentMobile.replaceWith(newMobile);var search=document.getElementById('service-search');if(search)search.dispatchEvent(new Event('input'));}).catch(function(){});}function closeFrame(backdrop){if(backdrop)backdrop.remove();refreshServices();}function showSaveDialog(form,message){var backdrop=form.closest('.service-open-backdrop');if(!backdrop)return;var old=backdrop.querySelector('.service-save-dialog');if(old)old.remove();var dialog=document.createElement('div');dialog.className='service-save-dialog';dialog.innerHTML='<section class="service-save-dialog__panel" role="alertdialog" aria-modal="true" aria-labelledby="service-save-title"><h2 id="service-save-title">Servicio guardado</h2><p></p><button type="button" class="btn btn-primary">Aceptar</button></section>';dialog.querySelector('p').textContent=message||'Los datos del servicio se guardaron correctamente.';var accept=function(){clearTimeout(timer);closeFrame(backdrop);};dialog.querySelector('button').addEventListener('click',accept);backdrop.appendChild(dialog);var timer=setTimeout(accept,3000);}function showFormError(form,message){var alert=form.querySelector('.service-save-error');if(!alert){alert=document.createElement('div');alert.className='alert alert-danger service-save-error';form.querySelector('.card-body').prepend(alert);}alert.textContent=message||'No se pudieron guardar los datos del servicio.';alert.scrollIntoView({block:'nearest'});}document.addEventListener('submit',function(event){var form=event.target;if(!form.matches('.service-open-backdrop #service-settings-form'))return;event.preventDefault();var button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Guardando…';}fetch(form.action,{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo guardar');return response.text();}).then(function(html){var doc=new DOMParser().parseFromString(html,'text/html'),success=doc.querySelector('.alert-success'),error=doc.querySelector('.alert-danger');if(success){showSaveDialog(form,success.textContent.trim());return;}showFormError(form,error?error.textContent.trim():'No se pudieron guardar los datos del servicio.');}).catch(function(){showFormError(form,'No se pudo guardar el servicio. Revisá los datos e intentá nuevamente.');}).finally(function(){if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Grabar';}});});})();</script>
<script>(function(){document.addEventListener('submit',function(event){var form=event.target;if(!form.matches('.service-open-backdrop .field-inline-modal form'))return;event.preventDefault();var fieldModal=form.closest('.field-inline-modal'),button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Guardando…';}fetch(form.action,{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo guardar');return response.text();}).then(function(html){var doc=new DOMParser().parseFromString(html,'text/html'),success=doc.querySelector('.alert-success'),error=doc.querySelector('.alert-danger');if(!success){var alert=form.querySelector('.service-save-error');if(!alert){alert=document.createElement('div');alert.className='alert alert-danger service-save-error';form.querySelector('.card-body').prepend(alert);}alert.textContent=error?error.textContent.trim():'No se pudieron guardar los datos de la cancha.';return;}var dialog=document.createElement('div');dialog.className='service-save-dialog';dialog.innerHTML='<section class="service-save-dialog__panel" role="alertdialog" aria-modal="true"><h2>Precio guardado</h2><p></p><button type="button" class="btn btn-primary">Aceptar</button></section>';dialog.querySelector('p').textContent=success.textContent.trim()||'Los datos de la cancha se guardaron correctamente.';var refreshService=function(){var serviceUrl=form.action.replace(/\/canchas\/\d+\/guardar$/,'');fetch(serviceUrl,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){if(!response.ok)throw new Error('No se pudo actualizar');return response.text();}).then(function(html){var doc=new DOMParser().parseFromString(html,'text/html'),currentPanel=fieldModal&&fieldModal.closest('.service-modal-panel'),currentPrices=currentPanel&&currentPanel.querySelector('#service-prices'),newPrices=doc.querySelector('.service-modal-panel #service-prices');if(currentPrices&&newPrices){newPrices.className=currentPrices.className;currentPrices.replaceWith(newPrices);}}).catch(function(){});};var close=function(){clearTimeout(timer);if(fieldModal){window.location.hash='';fieldModal.style.display='';}dialog.remove();refreshService();};dialog.querySelector('button').addEventListener('click',close);(fieldModal||form).appendChild(dialog);var timer=setTimeout(close,3000);}).catch(function(){var alert=form.querySelector('.service-save-error');if(!alert){alert=document.createElement('div');alert.className='alert alert-danger service-save-error';form.querySelector('.card-body').prepend(alert);}alert.textContent='No se pudo guardar el precio. Revisá los datos e intentá nuevamente.';}).finally(function(){if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Guardar cancha';}});});})();</script>
